 N=1<<n; q=sorted([n-2*j for j in range(n+1) for _ in range(comb(n,j))],reverse=True); beta=[sum(q[:k]) for k in range(N+1)]; M=max(beta); z=0; mp=None; g=0
 for a in range(1,N):
  for b in range(1,N-a+1):
   x=2*M*(a+b)+N*beta[a+b]-N*beta[a]-N*beta[b]; z+=x==0; g=gcd(g,x); mp=x if x>0 and (mp is None or x<mp) else mp
 print(n,N,M,N*beta[N],z,mp,g)')"

